        const unsigned char *uc = *ucp;
        int got = 0;

        DPRINTF("Parse number: ", uc, *ucp);
        if (uc == ue)
                return 0;
        if (*uc == '-')
                uc++;

        for (; uc < ue; uc++) {
                if (!json_isdigit(*uc))
                        break;
                got = 1;
