                if (*uc == '+' || *uc == '-')
                        uc++;
                for (; uc < ue; uc++) {
                        if (!json_isdigit(*uc))
                                break;
                        got = 1;
                }
        }
 out:
        if (!got)
                DPRINTF("Bad number: ", uc, *ucp);
        else
                DPRINTF("Good number: ", uc, *ucp);
        *ucp = uc;
        return got;
 }

 static int
 json_parse_const(const unsigned char **ucp, const unsigned char *ue,
     const char *str, size_t len, size_t lvl __file_debugused)
